      return { ok: false, conferir: true, motivo: "vão fora da tabela do fabricante (" + (L.length ? L[0].vao_mm + " a " + L[L.length - 1].vao_mm + " mm" : "vazia") + ") — não se extrapola", unidade: tab.unidade };
    var r = null;
