      if (v < L[i].vao_mm) { var a = L[i - 1], b = L[i]; r = a.cargaUniforme + (b.cargaUniforme - a.cargaUniforme) * (v - a.vao_mm) / (b.vao_mm - a.vao_mm); break; }
