  function preparo(id) { var q = chaveFrouxa(String(id == null ? "" : id).replace(/ ?1\/2/, "\u00bd")), x = null; preparos().forEach(function (p) { if (!x && (chaveFrouxa(p.id) === q || chaveFrouxa(p.iso) === q)) x = p; }); return x; }
