  var DUR_NOMES = { L: ["L", "BAIXA", "BAIXO", "LOW"], M: ["M", "MEDIA", "MEDIO", "MEDIUM"], H: ["H", "ALTA", "ALTO", "HIGH"], VH: ["VH", "MUITOALTA", "MUITOALTO", "VERYHIGH"] };
